@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@rendermode InteractiveServer

<PageTitle>Enrollment Request</PageTitle>

<div class="container mt-4">
    <h1>Enrollment Request</h1>
    <p class="text-muted">Complete this form to submit an enrollment request.</p>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been submitted successfully.</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <EditForm Model="_request" OnValidSubmit="HandleSubmit" FormName="enrollment" class="needs-validation">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger mb-3" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" class="form-control" @bind-Value="_request.StudentName" />
                <ValidationMessage For="() => _request.StudentName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" class="form-control" @bind-Value="_request.StudentId" />
                <ValidationMessage For="() => _request.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseSelect" class="form-label">Course</label>
                <InputSelect id="courseSelect" class="form-select" @bind-Value="_request.CourseId">
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in _courses)
                    {
                        <option value="@course.Id">@course.Code - @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _request.CourseId" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </EditForm>
    }
</div>

@code {
    private EnrollmentRequest _request = new();
    private List<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? QueryCourseId { get; set; }

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (QueryCourseId.HasValue)
            _request.CourseId = QueryCourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(_request.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Code} - {course.Title}" : "Unknown";
        _submitted = CatalogService.SubmitEnrollmentRequest(_request);
    }
}
